fn count_eligible(participations: &[u8], k: u8) -> usize {
    participations.iter()
        .filter(|&&attendance_count| 5 - attendance_count >= k)
        .count()
}

fn solve(n: u8, k: u8, participations: Vec<u8>) -> u8 {
    // Limit the number of participants to n
    let relevant_participations = &participations[..n.min(participations.len() as u8) as usize];
    
    // Count eligible participants
    let eligible_count = count_eligible(relevant_participations, k);
    
    // Calculate the maximum number of disjoint teams of 3
    (eligible_count / 3) as u8
}

fn main() {
    // Example usage
    let n = 5;
    let k = 2;
    let participations = vec![1, 2, 3, 4, 5, 0];
    
    let result = solve(n, k, participations);
    println!("Maximum number of teams: {}", result);
}